// P0-4 · Quotation PDF generated by the app from the approved snapshot.
// Graph's ?format=pdf converts the whole workbook (cost tabs included) and caps the source at
// 2 MB, so we render our own HTML template — customer-facing figures only — and print it.

import { renderQuotationHtml, type QuotationData } from '../../../src/domain/quotation.ts'
export { renderQuotationHtml, bahtText, quotationTotals, type QuotationData } from '../../../src/domain/quotation.ts'

// Only the slice of the Playwright API we use — keeps it an optional, runtime-only dependency.
interface Playwright {
  chromium: { launch(): Promise<{
    newPage(): Promise<{ setContent(html: string, o: { waitUntil: 'load' }): Promise<void>; pdf(o: { format: string; printBackground: boolean }): Promise<Buffer> }>
    close(): Promise<void>
  }> }
}
async function loadPlaywright(): Promise<Playwright> {
  const mod = 'playwright'
  try {
    return (await import(mod)) as Playwright
  } catch {
    // Globally installed Playwright is only visible to CommonJS resolution (NODE_PATH).
    const { createRequire } = await import('node:module')
    return createRequire(import.meta.url)(mod) as Playwright
  }
}

/** Render to PDF with headless Chromium (Playwright). Install `playwright` on the worker host. */
export async function renderQuotationPdf(q: QuotationData): Promise<Buffer> {
  const { chromium } = await loadPlaywright()
  const browser = await chromium.launch()
  try {
    const page = await browser.newPage()
    await page.setContent(renderQuotationHtml(q), { waitUntil: 'load' })
    return await page.pdf({ format: 'A4', printBackground: true })
  } finally {
    await browser.close()
  }
}
